Explain this code: class ProcessingPipeline:
    def __init__(self, job_id):
        self.job_id = job_id
        self.stages = []
    def add_stage(self, name, handler):
        self.stages.append({'name': name, 'handler': handler})
    def execute(self, context):
        result = context
        for idx, stage in enumerate(self.stages):
            result = stage['handler'](result)
        return result

Explain this code: def calculate_diff(source, target, path=''):
    differences = []
    if isinstance(source, dict):
        all_keys = set(source.keys()) | set(target.keys())
        for key in all_keys:
            differences.extend(calculate_diff(source.get(key), target.get(key), f'{path}.{key}'))
    elif source != target:
        differences.append({'path': path, 'type': 'modified', 'old': source, 'new': target})
    return differences
